contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint putAmount, uint collectAmount, uint lockTime) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= putAmount);
        c.Put{value: putAmount}(lockTime); if (__ESBMC_reverted()) return;

        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        require(balanceBefore == putAmount);

        uint minSum = c.MinSum(); if (__ESBMC_reverted()) return;
        require(balanceBefore >= minSum);
        require(balanceBefore >= collectAmount);
        require(block.timestamp > unlockTimeBefore);

        c.Collect(collectAmount); if (__ESBMC_reverted()) return;

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        assert(balanceAfter <= balanceBefore);
    }

    receive() external payable {}
}

