pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 putAmount, uint256 collectAmount, uint256 lockTime) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        try c.Put{value: putAmount}(lockTime) {} catch { return; }
        uint256 unlockTimeBefore;
        uint256 balanceBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTimeBefore = __r0; balanceBefore = __r1; } catch { return; }
        putAmount = balanceBefore;
        uint256 minSum;
        try c.MinSum() returns (uint256 __r) { minSum = __r; } catch { return; }
        vm.assume(balanceBefore >= minSum);
        vm.assume(balanceBefore >= collectAmount);
        vm.assume(block.timestamp > unlockTimeBefore);
        try c.Collect(collectAmount) {} catch { return; }
        uint256 unlockTimeAfter;
        uint256 balanceAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockTimeAfter = __r0; balanceAfter = __r1; } catch { return; }
        assertTrue(balanceAfter <= balanceBefore);
    }

    function testFuzz_run(uint256 putAmount, uint256 collectAmount, uint256 lockTime) public {
        _run(putAmount, collectAmount, lockTime);
    }

    receive() external payable {}
}
